        -- a token mapped to "" (or otherwise empty) denotes the empty word,
        -- exactly what the old parser's peek()=="" branch produced
        for i, token in ipairs(tokens) do
            if token == "" then
                tokens[i] = "λ"
            end
        end
        local input = table.concat(tokens)
        local grammar, repairs, ferr =
            make_regexp_grammar(tokens, lenient, metas)
        local ok, result = pcall(lpeg.match, grammar, input)
        if not ok then
            if type(result) == "table" then
                return nil, result
            end
            return nil, {kind = "error", tokidx = nil,
                         exp = nil, msg = result}
        end
        if not result then
            return nil, {kind = "operand", tokidx = ferr.pos,
                         exp = ferr.exp,
                         msg = "Expression expected"}
        end
        return result, repairs
    end

    -- the pre-refactor contract: success -> ast, repairs; failure ->
    -- raised string error (same messages, re-prefixed by error())
    local function parse_tokens_or_raise(tokens, lenient)
        local ast, res = parse_tokens(tokens, lenient)
        if not ast then
            error((res.msg or tostring(res))
                  :gsub("^[^:]+:%d+: *", ""))
        end
        return ast, res
    end

    -- https://matt.might.net/articles/parsing-regex-with-recursive-descent/

    function automata.parse_regexp(orig_next)
        local tokens = {}
        while true do
            local token = orig_next()
            if token == nil then
                break
            end
            tokens[#tokens + 1] = token
        end
        return parse_tokens_or_raise(tokens)
    end

    function automata.parse_regexp_string(word, map)
        assert(type(word) == "string")
        assert(type(map) == "table" or type(map) == "nil")

        word = util.remove_whitespace(word)
        local sequence = automata.tokenise_word(word, map)
        local tokens = {}
        for index = 1,sequence:len() do
            tokens[index] = sequence:get_char(index)
        end
        return (parse_tokens_or_raise(tokens))
    end

    -- editor-facing variant: the caller hands over its own token
    -- list (it owns the source anchoring) and gets a structured
    -- result — success: ast (nodes carry t0/t1 token-index spans)
    -- + repairs; failure: nil + errtab{kind,tokidx,exp,msg}.
    -- opts.lenient enables the grading spellings; opts.metas marks
    -- additional tokens as non-primitive (course notation: *, +, ^
    -- are operators, never symbols)
    function automata.parse_regexp_tokens(tokens, opts)
        opts = opts or {}
        return parse_tokens(tokens, opts.lenient, opts.metas)
    end

    -- lenient variant for grading: additionally accepts the spellings
    -- the grade_regexp gsub chains used to rewrite ("U" and "\cup"
    -- for union, "{…}" for a group, "\lambda" for the empty word) and
    -- reports each tolerance used as {kind=…, index=token-index} in
    -- the second return value.  Destructive cleanup ("A = …", leading
    -- "regular:", stray "^") stays preprocessing in the caller
    function automata.parse_regexp_string_lenient(word, map)
        assert(type(word) == "string")
        assert(type(map) == "table" or type(map) == "nil")

        word = util.remove_whitespace(word)
        local sequence = automata.tokenise_word(word, map)
        local tokens = {}
        for index = 1,sequence:len() do
            tokens[index] = sequence:get_char(index)
        end
        return parse_tokens_or_raise(tokens, true)
    end

    function automata.random_regexp(alphabet)
        local random_choices = {
            {5, "primitive"},
            {2, "blank"},
            {1, "empty"},
            {20, "repetition"},
            {20, "plus"},
            {40, "choice"},
            {200, "sequence"},
        }

        local function random_choice()
            local total = 0
            for _,choice in ipairs(random_choices) do
                total = total + choice[1]
            end
            local sample = math.random()
            local sofar = 0
            for _,choice in ipairs(random_choices) do
                sofar = sofar + choice[1] / total
                if sample < sofar then
                    return choice[2]
                end
            end
        end


        local pool = {}

        local function combine_regexp()
            local chosen
            repeat
                chosen = random_choice()
                if chosen == "primitive" then
                    local letter = alphabet[math.random(1,#alphabet)]
                    return automata.make_regexp_primitive(letter), {}
                elseif chosen == "blank" then
                    return automata.make_regexp_blank(), {}
                elseif chosen == "empty" then
                    return automata.make_regexp_empty(), {}
                elseif chosen == "repetition" then
                    if #pool < 1 then
                        chosen = nil
                    else
                        local where = math.random(1, #pool)
                        if pool[where]:get_type() == "regexp_repetition" or pool[where]:get_type() == "regexp_plus" then
                            chosen = nil
                        else
                            return automata.make_regexp_repetition(pool[where]), {where}
                        end
                    end
                elseif chosen == "plus" then
                    if #pool < 1 then
                        chosen = nil
                    else
                        local where = math.random(1, #pool)
                        if pool[where]:get_type() == "regexp_repetition" or pool[where]:get_type() == "regexp_plus"  then
                            chosen = nil
                        else
                            return automata.make_regexp_plus(pool[where]), {where}
                        end
                    end
                elseif chosen == "choice" then
                    if #pool < 2 then
                        chosen = nil
                    else
                        local where_a = math.random(1, #pool)
                        local where_b = math.random(1, #pool - 1)
                        if where_b >= where_a then
                            where_b = where_b + 1
                        end
                        return automata.make_regexp_choice(pool[where_a], pool[where_b]), {where_a, where_b}
                    end
                elseif chosen == "sequence" then
                    if #pool < 2 then
                        chosen = nil
                    else
                        local where_a = math.random(1, #pool)
                        local where_b = math.random(1, #pool - 1)
                        if where_b >= where_a then
                            where_b = where_b + 1
                        end
                        return automata.make_regexp_sequence(pool[where_a], pool[where_b]), {where_a, where_b}
                    end
                else
                    error()
                end
            until chosen
        end

        local function delete_from_pool(position)
            if position < #pool then
                pool[position] = pool[#pool]
            end
            pool[#pool] = nil
        end

        local function insert_to_pool(what)
            pool[#pool + 1] = what
        end

        for _=1,10 do
            local regexp, delete = combine_regexp()
            for i=1,#delete do
                local position = delete[i]
                delete_from_pool(position)
            end
            insert_to_pool(regexp)
            print(#pool)
        end

        local result = pool[math.random(1, #pool)]
        local aut = automata.regexp_to_nfa_lambda(result)
        aut = automata.nfa_to_dfa(aut)
        aut = automata.ref_sig_dfa(aut)
        aut = automata.make_dfa_incomplete(aut)
        aut = automata.simplify_state_names(aut)
        print(aut)
        return result
    end
end
